  if(game.boss&&game.boss.hp>0){let b=game.boss;b.hit=Math.max(0,b.hit-dt);b.phase+=dt;let engaged=spider.x>900; if(engaged){let target=clamp(spider.x+Math.sign(spider.x-b.x)*80,1260,1660);b.x+=(target-b.x)*Math.min(1,dt*.35);if(Math.sin(b.phase*1.4)>.96&&Math.abs(b.x-spider.x)<100)hurt(1);}
    // Room hazards are a boss-fight tool as well as scenery.
