    if(hazard&&Math.floor(b.phase*2.4)!==Math.floor((b.phase-dt)*2.4)){hitBoss(1,'hazard');toast(`The ${hazard.kind==='fan'?'fan':hazard.kind==='flower'?'flower':hazard.kind} caught it!`);}
  }
